    if isinstance(n,ast.ClassDef) and n.name!='DataStore':
        fields=[s.target.id for s in n.body if isinstance(s,ast.AnnAssign)]
        base=[b.id for b in n.bases if isinstance(b,ast.Name) and b.id!='BaseModel']
        py[n.name]=(base,fields)
def allf(c):
    b,f=py[c]; return sum((allf(x) for x in b),[])+f
ts=open('frontend/lib/types.ts').read()
tsd={}
for m in re.finditer(r'export interface (\w+)(?: extends (\w+))? \{(.*?)\n\}',ts,re.S):
    f=re.findall(r'^\s+(\w+)\??:',m.group(3),re.M); tsd[m.group(1)]=(m.group(2),f)
def tall(c):
    b,f=tsd[c]; return (tall(b) if b else [])+f
bad=0
for c in py:
    if c not in tsd: print('MISSING',c); bad=1; continue
    if allf(c)!=tall(c): print('DIFF',c,allf(c),tall(c)); bad=1
print('version', re.search(r'CONTRACT_VERSION = "(.*?)"',open('contracts/schemas.py').read()).group(1), re.search(r'CONTRACT_VERSION = "(.*?)"',ts).group(1))
print('OK: all', len(py), 'models match' if not bad else 'MISMATCH')
EOF
